import{_,c as e,o as t,ag as a,ai as o}from"./chunks/framework.C4JMckMd.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"diary/人生只有你自己，怎么会落后呢？.md","filePath":"diary/人生只有你自己，怎么会落后呢？.md"}'),r={name:"diary/人生只有你自己，怎么会落后呢？.md"};function i(l,p,s,m,c,n){return t(),e("div",null,p[0]||(p[0]=[a('<p><em>【封面图]</em><img src="'+o+'" alt="309"></p><blockquote><p>我的糖豆宝宝，回家再也看不到这个小家伙了，空荡荡的。失去这个坏猫也是我自找的，怨不来别人。</p></blockquote><p><em>【每天肯定自己的小进步】</em></p><ol><li><p>昨天有晚上算是早睡了吧，1点钟就睡了，然后早上是7点钟起的。没有睡够8个小时，但是已经睡得比之前早了两个小时。感觉今天下午上班的状态非常好。</p></li><li><p>已经把赘婿的最新篇章看完了，现在强制自己去看一些对个人成长有用的书，去看了《马斯克自传》。</p><p>我其实是带着偏见去看这种自传类型的小说的。但是这种自传类型它自带很多故事性，相比一些个人成长的成功学的书，它更加容易看得进去。</p><p>乔布斯的自传算是我见过最为火爆的一个自传了。在他之后，我发现陆续很多的企业家都在写他们的自传。包括雷军、任正非，以及马斯克也有。他们还能干很久，可能比绝大多数人都活得还能更加长。所以他们写自传的目的，出发点，我认为是不纯的，这就是我的偏见。</p><p>我认为他们出发点还是为了圆自己的故事。马斯克这本书，我只看了100多页，但是无时无刻不围绕着一点，就是马斯克这个人做事情很执拗，很有能力，少年天才，异于常人，对待目标有不达成不罢休的信念。很好圆他那个创火箭或者电动车的故事。这时代故事是值钱的，故事是能拉来投资的。</p></li><li><p>今天下班回家比较晚，到家差不多10点钟了。回家第一件事，我就马上把衣服洗了，一分钟也没耽误。然后就坐在位置上，做我今天该做的一些总结。给自己一个小小鼓励。拖延症-1。</p></li></ol><p><em>【今日份阅读启发】</em></p><p>人生只有你自己，怎么会落后呢？</p><p>马斯克自传里边，他其实有一个描述出来的马斯克有个很好的品质，那就是他做事情是有谋划的。他只跟自己进行相比，也对自己非常的有自信。他和阿甘一样，不在意外界对他们的评。他只做自己相信的事情，包括他小时候进入的天主教的学校，质疑宗教的，对于宗教的质疑，对于科学的一些向往，一个探索。他都在做自己认为对的事情，他没有在意自己跟其他人比，我是厉害还是不厉害。他只是对，他只对自己感兴趣事情往前走。在实现自己的目标的时候，这路上可能会碰到很多不同的困难，他都一一的去解决。</p><p>所以说不要给自己太大的压力。你只需要一直往前走就行了，就对了。只要你每一天都比昨天更进一步，那么你的人生就是有价值的。马斯克在小时候，在上了大学之后，就一直在探讨一个关系，一个问题，我们人类活下来的意义是什么？为什么而活？我们人生的价值是什么？这是我值得思考的一个。人生不需要一个对照的组，不管你往哪里走，只要你一直在走，你不摆烂，那么就是向前走的。因为你无法往回走，你只能向前走，你一定是进步的。</p>',8)]))}const u=_(r,[["render",i]]);export{f as __pageData,u as default};
